// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    float64   // bucket capacity
	tokens   float64   // available tokens
	last     time.Time // last refill time
	clock    Clock
}

// NewLimiter creates a Limiter allowing rate events per second with burst capacity.
func NewLimiter(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be > 0")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// AllowN reports whether n events may happen at time t.
func (l *Limiter) AllowN(t time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill tokens elapsed since last update.
	elapsed := t.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = t
	}

	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether a single event may happen now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
