// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created by NewLimiter and is safe for concurrent use.
type Limiter struct {
	mu        sync.Mutex
	rate      float64 // tokens per second
	burst     float64 // bucket capacity
	tokens    float64
	lastRefill time.Time
	clock     Clock
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// NewLimiter creates a Limiter that refills at rate tokens per second,
// with a maximum capacity (burst) of burst tokens. The bucket starts full.
func NewLimiter(rate, burst float64, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		return nil, ErrNilClock
	}
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: burst,
		clock:  clock,
	}, nil
}

// NewRealClockLimiter is a convenience constructor using the real clock.
func NewRealClockLimiter(rate, burst float64) (*Limiter, error) {
	return NewLimiter(rate, burst, realClock{})
}

// refill advances the bucket's token count to time now.
// Caller must hold l.mu.
func (l *Limiter) refill(now time.Time) {
	elapsed := now.Sub(l.lastRefill).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
	}
	l.lastRefill = now
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are consumed; otherwise the bucket is unchanged.
// n must be >= 0; a negative n returns false without side effects.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// Tokens returns the current number of available tokens (for diagnostics).
func (l *Limiter) Tokens() float64 {
	now := l.clock.Now()
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	return l.tokens
}
