		t.Run(tc.name, func(t *testing.T) {
			l, err := NewLimiter(tc.rate, tc.burst, tc.clock)
			if tc.wantErr != nil {
				if err != tc.wantErr {
					t.Fatalf("got err %v, want %v", err, tc.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if l == nil {
				t.Fatal("nil limiter on success")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	tests := []struct {
