			rate: 2, burst: 4,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 4, true},
				{0, 1, false},
				{500 * time.Millisecond, 1, true},
				{0, 1, false},
				{250 * time.Millisecond, 1, true},
				{0, 1, false},
			},
		},
		{
			name: "cap at burst",
			rate: 10, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{time.Hour, 2, false},
				{0, 1, true},
			},
		},
		{
			name: "zero tokens always allowed",
			rate: 1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 0, true},
				{0, 0, true},
