			l, err := NewLimiter(tc.rate, tc.burst, clock)
			if err != nil {
				t.Fatalf("NewLimiter: %v", err)
			}
			for i, s := range tc.steps {
				clock.Advance(s.advance)
				if got := l.AllowN(clock.Now(), s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestAllow(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	l, err := NewLimiter(1, 1, clock)
	if err != nil {
		t.Fatalf("NewLimiter: %v", err)
	}
	if !l.Allow() {
		t.Fatal("first Allow = false, want true")
	}
	if l.Allow() {
		t.Fatal("second Allow = true, want false")
	}
	clock.Advance(time.Second)
	if !l.Allow() {
		t.Fatal("Allow after refill = false, want true")
	}
}

func TestConcurrentUse(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	l, err := NewLimiter(1000, 100, clock)
	if err != nil {
		t.Fatalf("NewLimiter: %v", err)
	}
	var mu sync.Mutex
	allowed := 0
	var wg sync.WaitGroup
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.AllowN(clock.Now(), 1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Fatalf("allowed %d requests, want 100", allowed)
	}
}
